def add(title,lead='',items=(),code='',label='Claude Code에 입력',note='',src=(),kind='',answer=''):
 S.append(dict(chapter=chapter,title=title,lead=lead,items=list(items),code=code,label=label,note=note,sources=list(src),kind=kind,answer=answer))
def section(name,desc,time):
 global chapter
 chapter=name
 add(name,desc,[time],note='이 장의 학습 목표를 먼저 소개한다. 용어를 설명한 뒤 한 번 시연하고, 수강자가 직접 같은 결과를 확인하게 한다.',kind='section')
add('Claude Code\n처음부터 에이전트까지','터미널이 처음인 사람을 위한 실습형 가이드',['AI·LLM 기초 / 파일 작업 / 검증 / 업무 자동화','공식 문서 확인 2026.11.02 · 6시간 과정'],note='이 수업은 프로그래밍 경험을 전제로 하지 않는다. 가상 회사의 온보딩 자료를 일관된 예제로 사용한다. 고급 모듈은 강사가 먼저 시연하고 선택 실습으로 운영한다. 실제 개인정보를 가져오지 않도록 시작 전에 안내한다.',kind='cover')
add('수업이 끝나면 할 수 있는 일','작업을 요청하고, 결과를 확인하고, 반복 절차를 재사용합니다.',['터미널에서 올바른 폴더를 열고 Claude Code 시작하기','근거가 있는 요약문과 HTML 안내문 만들기','변경 내용·오류·비용을 확인하고 잘못된 작업 되돌리기','Skill과 서브에이전트로 작업을 나누고 검토하기'],note='완료 기준은 명령 암기가 아니다. 내 파일이 어디 있는지, 무엇이 바뀌었는지, 결과가 맞다는 근거가 무엇인지 설명할 수 있으면 된다.')
add('전체 목차와 권장 시간','총 360분 + 휴식 30분 · 두 번의 3시간 수업으로 분리 가능',['01 AI·LLM·Agent 30분 / 02 터미널·설치 45분','03 첫 작업·프롬프트 45분 / 04 검증·복구·보안 40분','05 컨텍스트·지침 35분 / 06 Skills·MCP·Hooks 45분','07 에이전트·자동화 50분 / 08 종합 실습·정리 70분'],note='1회차는 1~4장과 5장 앞부분, 2회차는 나머지와 종합 실습으로 운영한다. 빠른 2시간 과정은 설치를 사전 과제로 두고 1·3·4장과 종합 실습 일부를 선택한다. 각 시간은 권장 운영안이다.')
add('덱 사용법과 준비물','인터넷은 Claude Code 사용에 필요합니다. 슬라이드는 오프라인에서도 열립니다.',['← → 또는 Space: 이동 / T: 목차·검색 / N: 강사 노트','F: 전체 화면 / P: 인쇄·PDF / Home·End: 처음·끝','준비: PC, 브라우저, 사용 가능한 계정, 실습 폴더','실습 자료는 workshop/materials, 결과는 workshop/output'],note='하단 버튼으로도 모든 기능을 사용할 수 있다. 발표 화면에 강사 노트를 켜면 청중에게도 보이므로 사전 준비·자습용으로 사용한다. HTML 파일을 직접 열 수 있다. 코드 복사가 차단되는 브라우저에서는 블록을 선택하여 복사한다.')
section('01 · AI, LLM, Agent','무엇을 잘하고, 왜 틀리고, 어떻게 행동하는가','30분 · 개념 + 짧은 토론')
add('AI와 LLM의 관계','LLM은 언어를 다루는 AI 모델의 한 종류입니다.',['AI: 지능적인 과업을 수행하도록 만드는 기술의 넓은 범주','머신러닝: 데이터에서 패턴을 학습하는 방법','생성형 AI: 텍스트·이미지·소리 등 새 결과를 생성','LLM: 대규모 데이터로 학습한 언어 모델'],note='분류 AI의 예는 메일 스팸 판별, 생성형 AI의 예는 메일 초안 작성이다. LLM이 모든 AI를 뜻하는 것은 아니다. 이미지를 입력받는 모델은 멀티모달 기능도 갖는다.',src=['llm'])
add('LLM은 토큰을 이어서 생성한다','토큰은 모델이 텍스트를 처리하는 조각입니다.',['문장 → 토큰 → 문맥을 반영한 다음 토큰 예측 → 답변','토큰은 단어와 같지 않으며 언어·기호에 따라 나뉨','자연스러운 문장이라고 사실이라는 뜻은 아님'],note='교육용 비유: 문장을 이어 쓰는 능력이 매우 발달한 시스템이다. 단순 자동완성과 완전히 같다는 뜻은 아니며, 학습을 통해 복잡한 언어 표현과 과업 수행 능력도 얻는다. 한국어 글자 수로 토큰 수를 정확히 계산하지 않는다.',src=['llm'])
add('학습과 추론은 다른 단계','대화 중 파일을 읽는 것과 모델 자체를 다시 학습하는 것은 다릅니다.',['학습: 많은 데이터로 모델의 내부 매개변수를 조정','추론: 현재 입력과 문맥을 바탕으로 결과를 생성','대화에 준 정보는 현재 답변의 근거가 될 수 있음','장기 기억·데이터 보관·모델 학습 정책은 각각 별개'],note='회사 규정을 붙여 주면 지금의 답변에 활용할 수 있다. 이것이 모든 사용자를 위한 모델의 지식이 즉시 바뀐다는 뜻은 아니다. 서비스의 데이터 사용 정책은 별도로 확인한다.',src=['llm','data-usage'])
add('컨텍스트는 지금 펼쳐 둔 작업 자료','대화, 지침, 파일 내용, 도구 결과가 함께 들어갑니다.',['모델이 현재 참고할 수 있는 정보에는 길이 한계가 있음','관계없는 로그와 오래된 지시는 집중을 방해할 수 있음','핵심 사실·결정·미해결 항목을 짧게 보존하면 유리'],note='책상 비유를 사용한다. 자료를 많이 쌓는 것보다 필요한 자료를 찾기 쉽게 놓는 것이 중요하다. 긴 컨텍스트를 지원해도 모든 세부 정보를 동일하게 잘 활용하는 것은 아니다.',src=['context'])
add('환각과 불확실성','모르는 내용을 그럴듯하게 채워 넣을 수 있습니다.',['존재하지 않는 규정, 링크, 함수, 인용문을 만들 수 있음','최신 정보는 검색한 날짜와 원문을 확인','수치 계산은 계산 도구나 프로그램으로 재검산','근거가 없으면 “확인 필요”로 남기도록 요청'],note='실습 질문: 자료에 없는 복지비를 물으면 어떤 답이 좋은가? 정답은 임의의 금액이 아니라 근거가 없다는 표시와 담당자 확인이다. 모델에게 자신감을 물어보는 것만으로 사실 검증을 대신할 수 없다.',src=['best-practices'])
add('검색·RAG·파일 읽기','외부 근거를 가져와 답변에 사용하는 방식입니다.',['검색: 필요한 웹 페이지나 문서 위치를 찾음','RAG: 관련 자료를 검색해 생성 과정의 문맥에 제공','파일 읽기: 지정한 로컬 자료의 실제 내용을 참고','근거가 있어도 오래된 문서·충돌·누락을 확인'],note='RAG는 검색 증강 생성의 약자다. Claude Code의 파일 탐색을 설명할 때 반드시 별도 벡터 데이터베이스가 필요하다고 설명하지 않는다. 이 수업에서는 파일 검색과 읽기만으로 충분하다.',src=['context'])
add('채팅과 에이전트의 차이','에이전트는 목표를 위해 도구를 선택하고 결과를 보고 다음 행동을 정합니다.',['채팅 예: “안내문을 어떻게 쓰면 좋을까?”','에이전트 예: “자료를 읽고 안내문 파일을 만들고 확인해줘.”','도구: 파일 검색·읽기·수정·명령 실행·외부 연결','사용자: 목표와 범위, 허용할 행동, 완료 기준을 결정'],note='도구가 없는 모델의 답변은 컴퓨터의 파일을 직접 바꾸지 않는다. 에이전트는 실제 행동을 수행할 수 있으므로 검토 지점이 필요하다. 도구를 쓰는 모든 시스템이 완전 자율적이라는 뜻은 아니다.',src=['how-claude-code-works'])
add('워크플로와 에이전트','정해진 순서가 좋은 일과, 상황별 판단이 필요한 일을 구분합니다.',['워크플로: 정해 둔 순서로 분류 → 요약 → 저장','에이전트: 결과를 보고 필요한 자료와 다음 행동을 선택','단순하고 반복적인 일은 고정 절차부터 시작','복잡성이 늘면 지연·비용·오류 관리도 늘어남'],note='정해진 양식으로 파일명을 바꾸는 작업에는 짧은 스크립트가 더 나을 수 있다. 문서마다 형식이 달라 해석과 확인이 필요한 경우 에이전트가 도움이 될 수 있다.',src=['agents'])
add('Claude와 Claude Code','같은 모델 계열을 사용해도 작업 환경과 도구가 다릅니다.',['Claude 채팅: 대화와 자료 분석 중심의 인터페이스','Claude Code: 프로젝트 파일과 개발 도구를 다루는 에이전트','터미널·IDE·Desktop·웹 등 여러 인터페이스 제공','이번 수업은 로컬 폴더에서 쓰는 터미널 CLI 중심'],note='코딩 외에도 문서 작성과 파일 정리 같은 작업에 사용할 수 있다. 웹·Desktop·IDE는 실행 환경과 가용 기능에 차이가 있으므로 화면이 완전히 같다고 약속하지 않는다.',src=['overview'])
add('확인 질문 · 어떤 작업을 맡길까?','다음 중 가장 좋은 첫 과제는 무엇일까요?',['A. 실제 직원 전체의 평가 등급을 자동 결정','B. 가상 규정 1개에서 첫날 준비물 5개 추출','C. 전사 시스템을 한 번에 교체하고 바로 배포'],answer='B. 자료와 범위가 작고, 결과를 사람이 쉽게 대조할 수 있습니다.',note='A는 고위험 의사결정이며 실제 민감정보까지 포함한다. C는 작업 범위와 검증 비용이 너무 크다. 작은 과제로 성공 기준을 익힌다.',kind='quiz')
section('02 · 터미널 기초와 설치','명령을 외우기 전에, 지금 어디에 입력하는지 확인하기','45분 · 설치 + 폴더 탐색')
add('터미널·셸·CLI','터미널은 글자로 컴퓨터와 대화하는 창입니다.',['터미널: 입력과 출력을 보여 주는 창','셸: 명령을 해석하는 프로그램, 예: zsh·PowerShell','CLI: 명령어로 조작하는 프로그램의 인터페이스','claude: Claude Code를 시작하는 명령'],note='웹 주소창이나 Python 창에 명령을 붙여 넣지 않는다. 터미널 안에서 Claude가 실행되면 같은 창이라도 입력을 받는 프로그램이 달라진다.',src=['terminal-guide'])
add('운영체제별 터미널 열기','수업에서는 macOS와 Windows PowerShell을 기준으로 합니다.',['macOS: Spotlight 검색 → Terminal 또는 터미널','Windows: 시작 메뉴 → PowerShell 또는 Windows Terminal','Linux: 배포판의 Terminal 앱','Windows Terminal 안의 탭이 PowerShell인지 확인'],note='Windows Terminal은 여러 셸을 담는 앱이다. PS로 시작하는 프롬프트는 PowerShell의 단서다. Git Bash·WSL·CMD 명령을 섞지 않는다. 설치 시 조직의 소프트웨어 정책을 따른다.',src=['terminal-guide'])
add('경로와 현재 폴더','같은 명령이라도 어느 폴더에서 실행하는지에 따라 결과가 달라집니다.',['폴더 = 디렉터리 / 현재 폴더 = 지금 작업하는 위치','절대 경로: 컴퓨터의 기준점부터 전체 위치','상대 경로: 현재 폴더를 기준으로 한 위치','.. 은 상위 폴더, ~ 는 홈 폴더, 공백 있는 경로는 따옴표'],code='cd "내 프로젝트 경로"',label='OS 터미널 · 경로는 실제 위치로 교체',note='탐색기/Finder에서 workshop 폴더를 찾고 전체 경로를 복사하게 한다. 초보자는 홈 폴더 전체에서 시작하기 쉽다. 실제 업무 폴더 대신 제공한 연습 폴더를 사용한다.',src=['terminal-guide'])
add('기본 명령 · macOS / Linux','한 줄씩 실행하고 결과를 읽습니다.',code='pwd\nls\nmkdir claude-practice\ncd claude-practice\npwd\ncd ..',label='OS 터미널 · macOS / Linux',items=['pwd: 현재 위치 / ls: 목록 / mkdir: 폴더 생성 / cd: 이동'],note='같은 이름의 폴더가 이미 있으면 mkdir 단계는 건너뛴다. 이 명령들은 셸에 입력한다. 명령 앞에 보이는 $나 사용자 이름은 복사하지 않는다. 실습 배포 폴더는 다음 단계에서 별도로 연다.',src=['terminal-guide'])
add('기본 명령 · Windows PowerShell','PowerShell의 정식 명령 이름으로 확인합니다.',code='Get-Location\nGet-ChildItem\nNew-Item -ItemType Directory claude-practice\nSet-Location claude-practice\nGet-Location\nSet-Location ..',label='OS 터미널 · PowerShell',note='cd, ls 같은 별칭도 있지만 먼저 정식 이름과 의미를 알려 준다. 기존 폴더가 있다면 생성 단계를 건너뛴다. 한국어 경로가 문제일 때만 짧은 영문 경로로 연습 환경을 단순화한다.',src=['terminal-guide'])
add('세 종류의 입력을 구별하기','슬라이드의 코드 위에 있는 입력 위치를 확인합니다.',['OS 터미널: claude --version, cd, git status','Claude Code 내부: 자연어 요청, /help, /usage','파일 내용: CLAUDE.md, SKILL.md, JSON 설정'],note='셸에서 “이 문서를 요약해줘”라고 입력하면 명령을 찾을 수 없다는 오류가 날 수 있다. 반대로 Claude 내부에서 셸 명령을 그냥 입력하면 자연어 요청으로 해석할 수 있다. !로 직접 실행하는 고급 기능은 첫 실습에서는 사용하지 않는다.',src=['interactive-mode','cli-reference'])
add('복사·실행·중단','입력 전 명령 전체를 읽고, 실행 후 출력이 끝날 때까지 기다립니다.',['macOS 붙여넣기: Cmd+V / Windows Terminal: Ctrl+Shift+V','Enter: 실행 / ↑: 이전 명령 / Tab: 경로 자동 완성','Ctrl+C: 실행 중인 작업 중단 또는 입력 취소','복사한 명령의 URL·경로·삭제 옵션을 확인'],note='터미널마다 붙여넣기 키는 다를 수 있다. Ctrl+C가 복사가 아니라 중단인 경우가 많다는 점을 보여 준다. 중단해도 이미 저장한 파일이나 외부 행동이 자동으로 되돌아가는 것은 아니다.',src=['terminal-guide','interactive-mode'])
add('설치 전 확인','계정과 네트워크를 먼저 준비하면 실습 중 막히는 시간을 줄일 수 있습니다.',['공식 지원 OS와 조직의 설치 정책 확인','Claude 구독 또는 Console·조직 제공 접근 권한 준비','네이티브 설치는 Node.js 설치를 전제로 하지 않음','Windows의 Bash 작업에는 Git for Windows가 권장됨'],note='현재 문서는 macOS 13 이상, Windows 10 1809 이상 등을 안내한다. 지원 환경은 setup 문서에서 확인한다. API 결제와 Claude 구독은 같은 과금 계정이라고 가정하지 않는다. 개인 키를 강의 채팅방에 올리지 않는다.',src=['setup','quickstart'])
add('설치 · macOS / Linux / WSL','공식 설치 명령입니다. 내용을 이해한 후 실행합니다.',code='curl -fsSL https://claude.ai/install.sh | bash',label='OS 터미널 · macOS / Linux / WSL',items=['공식 서버에서 스크립트를 받아 bash로 실행하는 명령','완료 후 새 터미널을 열고 claude --version 확인'],note='|는 앞 명령의 출력을 뒤 명령의 입력으로 연결하는 파이프다. 출처를 모르는 설치 스크립트를 같은 방식으로 실행하지 않는다. 다운로드 중 출력이 없을 수 있다. 회사 기기에서는 관리자가 승인한 설치 방식을 사용한다.',src=['quickstart'])
add('설치 · Windows PowerShell','CMD가 아닌 PowerShell 탭에 입력합니다.',code='irm https://claude.ai/install.ps1 | iex',label='OS 터미널 · PowerShell',items=['공식 스크립트를 다운로드하여 PowerShell에서 실행','완료 후 새 창에서 claude --version 확인'],note='irm은 Invoke-RestMethod, iex는 Invoke-Expression 별칭이다. 환경 오류를 해결하려고 보안 정책을 전역으로 완화하지 않는다. WinGet 등 다른 설치 방식은 공식 setup 문서를 참고한다.',src=['quickstart','setup'])
add('설치 확인과 첫 로그인','버전 확인 → 실습 폴더 이동 → 실행 순서입니다.',code='claude --version\ncd "실습 자료의 workshop 폴더 경로"\nclaude --permission-mode default',label='OS 터미널 · 경로 교체 후 한 줄씩',items=['브라우저 로그인에서 사용할 계정·조직을 확인','폴더 신뢰 질문은 현재 연습 폴더가 맞는지 보고 선택'],note='default는 직접 검토하는 Manual 모드의 설정값이다. 현재 버전에서는 auto로 시작할 수 있으므로 교육용으로 명시한다. 조직 설정은 이 선택보다 우선할 수 있다. 로그인 안내와 폴더 신뢰 화면의 세부 표현은 버전에 따라 달라진다.',src=['quickstart','permission-modes'])
add('구독·API·사용량','로그인 방법에 따라 비용과 한도가 달라집니다.',['구독 사용량과 Console API 사용료를 구별','환경의 API 키가 구독 대신 사용될 수 있으므로 확인','/usage로 사용량 확인, 실제 청구는 계정의 결제 화면 확인','가격·모델·한도는 수업 당일 공식 페이지에서 재확인'],note='정액 구독을 무제한으로 설명하지 않는다. /usage에 보이는 API 환산 금액이 구독자의 실제 청구액과 같지는 않다. 회사가 제공한 계정과 개인 결제를 섞지 않도록 한다.',src=['costs','quickstart'])
add('설치·로그인 문제 해결','오류 문구를 그대로 보존하면 원인 찾기가 쉬워집니다.',['command not found: 새 터미널 → 설치 경로·PATH 확인','로그인·403: 계정·조직 권한·프록시 확인','claude doctor: 설치 상태 진단','명령과 오류를 함께 전달하되 키·개인 경로는 가림'],note='PATH는 셸이 프로그램을 찾는 폴더 목록이다. 무작정 재설치하거나 sudo를 붙이지 않는다. 업데이트 방법은 설치 방식에 맞춘다. 네이티브와 패키지 관리자를 섞으면 여러 설치본이 생길 수 있다.',src=['setup','troubleshooting'])
add('실습 준비 확인','모두 같은 가상 자료에서 시작합니다.',['workshop/materials에 policy.md, faq.md, schedule.csv 확인','Claude Code에서 /help를 입력해 도움말 확인','현재 폴더와 파일 목록을 읽기만 하도록 요청','실제 회사 문서나 직원 정보는 이 연습에 넣지 않음'],code='현재 작업 폴더와 materials 안의 파일 이름을 알려줘.\n파일은 수정하지 마.',note='강사는 모든 수강자가 workshop 폴더를 열었는지 확인한다. 출력에 materials가 없으면 경로부터 수정한다. 파일 개수와 이름만 보는 단계에서는 내용을 추정하지 않도록 한다.',src=['commands'])
section('03 · 첫 작업과 프롬프트','읽고, 요청하고, 확인하는 작은 작업부터','45분 · 첫 번째 실습')
add('첫 대화는 탐색부터','무엇이 있는지 이해한 뒤 결과물을 만듭니다.',code='materials 폴더를 읽고 각 파일의 목적을 설명해줘.\n자료끼리 충돌하거나 빠진 정보가 있으면 구분해서 알려줘.\n각 설명에 근거 파일을 적고, 아직 수정하지 마.',note='예상 관찰: 가상 정책과 FAQ의 출근 시각이 다르다. 파일 이름만 읽은 답변인지 실제 내용을 읽은 답변인지 도구 사용 기록에서 확인한다. 답변 형식보다 근거를 우선한다.',src=['common-workflows'])
add('좋은 요청의 다섯 요소','목표 · 자료 · 제약 · 결과물 · 확인 방법',['목표: 신입사원이 첫날 준비물을 알게 하기','자료: materials/policy.md와 schedule.csv','제약: 없는 사실은 만들지 않기, 원본 보존','결과물·검증: output/checklist.md, 항목마다 근거 표기'],note='페르소나를 길게 쓰는 것보다 결과물이 만족해야 하는 조건을 구체화한다. 한 요청에 모든 후속 업무를 넣지 않는다. 첫 단계는 쉽게 검사할 수 있는 문서 한 개다.',src=['best-practices'])
add('모호한 요청을 구체화하기','“좋게 정리해줘”는 결과의 기준이 없습니다.',code='신입사원용 첫날 체크리스트를 만들어줘.\nmaterials만 근거로 사용하고 output/checklist.md에 저장해줘.\n준비물, 시간·장소, 담당자, 확인이 필요한 항목으로 나눠줘.\n항목마다 근거 파일명을 붙이고, 추측한 내용은 넣지 마.\n원본 파일은 수정하지 말고 완료 후 빠진 항목을 점검해줘.',note='원본을 보존해 달라는 지시 자체가 기술적 접근 차단은 아니다. 실습에서는 권한과 변경 내역도 함께 확인한다. 출력 경로를 정하면 나중에 결과물을 찾기 쉽다.',src=['best-practices'])
add('파일과 화면을 정확히 가리키기','대상 위치를 알려 주면 불필요한 탐색이 줄어듭니다.',['@materials/policy.md처럼 파일을 참조','오류는 문구·재현 순서·기대 결과와 함께 제공','화면 문제는 스크린샷과 브라우저 크기도 전달','큰 파일은 관련 구간과 질문을 먼저 좁힘'],note='@ 자동 완성으로 실제 파일이 선택되는지 확인한다. 이미지 붙여넣기는 터미널과 OS에 따라 키가 다르다. API 키나 개인정보가 포함된 스크린샷은 사용하지 않는다.',src=['interactive-mode','common-workflows'])
add('계획 모드가 유용한 때','여러 파일을 바꾸거나 요구사항이 불분명할 때 사용합니다.',code='claude --permission-mode plan',label='OS 터미널 · 새 세션 시작 예',items=['대화 중에는 Shift+Tab으로 모드를 바꾸고 상태 확인','먼저 범위·단계·검증 방법을 검토한 뒤 구현 진행'],note='계획 모드는 분석과 계획에 적합하다. 허용 명령의 세부 동작은 버전과 정책에 따라 다르므로 완전한 보안 격리라고 설명하지 않는다. 간단한 오탈자 수정까지 반드시 계획 모드로 시작할 필요는 없다.',src=['permission-modes'])
add('계획 검토의 네 가지 질문','실행 전에 잘못된 가정을 찾아냅니다.',['변경할 파일이 내가 요청한 범위인가?','원본·민감정보·외부 서비스에 영향이 있는가?','검증 절차로 실제 요구사항을 확인할 수 있는가?','애매한 사실을 임의로 결정하고 있지 않은가?'],note='교육용 예: FAQ와 정책의 시간이 충돌할 때 “더 최신 같아 보이는 문서”를 임의로 선택하지 않는다. 날짜나 우선순위가 명시되지 않았으면 확인 필요로 둔다.')
add('피드백은 관찰 가능한 차이로','“이상해” 대신 위치·현재 상태·원하는 상태를 전달합니다.',code='output/checklist.md의 출근 시간이 단정적으로 적혀 있어.\npolicy.md와 faq.md의 시간이 다르므로 두 값을 함께 적고\n“담당자 확인 필요”로 바꿔줘. 다른 항목은 유지해줘.\n수정 후 바뀐 부분만 설명해줘.',note='매번 전체를 다시 작성시키면 잘 된 부분까지 바뀔 수 있다. 고칠 위치와 유지할 범위를 알려 준다. 같은 수정이 반복되면 자료나 조건을 다시 정리하고 새 계획을 만든다.')
add('실습 1 · 첫날 체크리스트','12분 · 자료 탐색 3분 → 작성 5분 → 대조 4분',['입력: 가상 정책·FAQ·일정 파일','산출물: output/checklist.md','성공: 준비물·시간·장소·담당자·충돌 표시','짝 활동: 서로의 결과에서 근거 2개를 원문과 대조'],note='기대 결과: 신분증과 개인 이어폰, 7층 교육실, 운영 담당자, 09:30과 10:00의 충돌이 드러난다. 2층이라는 과거 FAQ 장소도 현행 정책과 충돌하므로 확인 필요로 표시한다. 모든 결과를 동일한 문장으로 만들 필요는 없다.',kind='lab')
add('실습 1 · 확인 포인트','예쁘게 정리된 문서보다 근거를 먼저 봅니다.',['준비물: 신분증·개인 이어폰이 있는가?','장소 충돌: 7층 교육실과 2층 세미나실을 발견했는가?','시간 충돌: 09:30과 10:00을 단정하지 않았는가?','없는 정보: 식대 금액을 임의로 만들지 않았는가?'],note='자료의 충돌은 의도된 교육 요소다. 수강자가 어느 문서가 진실인지 맞히게 하지 않는다. 강사 노트에서 정답을 확인한 뒤 결과물에 미확정 표시를 남기는 능력을 평가한다.')
section('04 · 검증, 복구, 보안','에이전트가 했다는 말과 실제 결과를 구분하기','40분 · 변경 검토 + 두 번째 실습')
add('작업 루프를 읽는 법','자료 수집 → 실행 → 결과 확인 → 필요한 수정',['파일 검색·읽기: 무엇을 근거로 삼는가','파일 수정·명령 실행: 어떤 상태를 바꾸는가','검증: 명령·출력·화면으로 결과를 확인하는가','완료 보고: 바뀐 파일과 남은 문제를 설명하는가'],note='완료 보고에 “테스트 통과”라고 적혀 있어도 실행 기록이 없다면 다시 묻는다. 설명 생성과 도구 실행은 다른 사건이다.',src=['how-claude-code-works'])
add('권한 모드 선택','수업에서는 Manual(default)로 행동을 직접 확인합니다.',['default: 변경과 명령 실행을 직접 검토하는 출발점','acceptEdits: 파일 수정 등의 자동 허용 범위 확대','plan: 구현 전에 분석과 계획','auto: 자동 위험 검토 / bypassPermissions: 격리 환경의 고급 용도'],note='2026-11-02 문서 기준 인터랙티브 기본 모드가 auto일 수 있다. 모드 전환 순서를 외우지 말고 상태 표시를 읽는다. dontAsk는 필요한 승인을 자동 허용하는 모드가 아니라 승인되지 않은 도구를 거부하는 용도다.',src=['permission-modes'])
add('권한 요청에서 볼 내용','“허용”을 누르기 전 작업 대상과 영향을 읽습니다.',['어떤 도구가 어떤 파일·명령·서버에 접근하는가?','이번 한 번 허용인가, 반복 허용 규칙인가?','삭제·패키지 설치·외부 전송·배포가 포함되는가?','이해되지 않으면 먼저 명령의 의미를 설명하도록 요청'],note='작업 목적에 맞는 최소 범위를 허용한다. 수업에서 권한 우회 옵션을 기본 명령으로 제공하지 않는다. 이미 승인한 작업을 매번 불필요하게 묻도록 설계할 필요는 없지만, 영향이 바뀌면 다시 판단한다.',src=['security'])
add('diff는 변경 전후의 차이','추가된 줄과 삭제된 줄을 함께 봅니다.',['초록/+: 추가 / 빨강/−: 삭제, 도구별 표시 차이 있음','요청과 무관한 파일이 바뀌었는지 확인','숫자·링크·개인정보·설정·의존성 변경을 주의 깊게 검토','Claude 내부 /diff 또는 Git·IDE의 변경 화면 사용'],note='색상만으로 판별하지 않고 +와 -도 확인한다. 파일을 새로 만들었다면 전체 내용이 검토 대상이다. Git의 기본 diff는 추적하지 않는 새 파일을 표시하지 않으므로 status와 함께 본다.',src=['interactive-mode'])
add('검증의 종류','서로 다른 오류를 잡으려면 서로 다른 확인이 필요합니다.',['내용 검증: 자료와 날짜·숫자·주장을 대조','실행 검증: 프로그램이 오류 없이 실행되는지 확인','행동 검증: 실제 사용 흐름과 예외 입력을 시도','회귀 검증: 수정 전 되던 기능도 계속 되는지 확인'],note='예: 버튼이 존재한다는 것은 클릭이 작동한다는 증거가 아니다. 테스트가 모두 통과해도 테스트에 없는 요구사항은 실패할 수 있다. HTML 실습에서는 브라우저로 열어 실제 체크박스와 모바일 폭을 확인한다.')
add('Git은 프로젝트의 변경 기록','선택한 상태를 커밋으로 저장해 비교와 복구에 사용합니다.',['저장: 파일의 현재 내용을 디스크에 기록','커밋: 선택한 변경을 프로젝트 이력으로 남김','브랜치: 다른 작업 흐름을 분리','push: 원격 서버로 전송, 로컬 저장과 구별'],note='Git은 설치가 필요하며 GitHub와 같은 서비스 자체를 뜻하지 않는다. 실습 전 폴더를 복사해 두는 방법도 가능하다. 초보자에게 대량 삭제나 강제 초기화 명령을 해결책으로 권하지 않는다.')
add('Git 최소 확인 명령','이미 Git 저장소인 프로젝트에서 사용합니다.',code='git status\ngit diff\ngit diff --staged',label='OS 터미널 · Git 설치 및 저장소 필요',items=['status: 변경·추적 상태 / diff: 아직 스테이징하지 않은 차이','--staged: 커밋 대상으로 선택한 차이'],note='not a git repository 오류는 저장소 밖에 있다는 뜻일 수 있다. 이번 workshop은 Git 없이도 실습 가능하다. 새 파일은 status로 확인하고 파일 자체를 열어 검토한다. 커밋을 가르칠 때는 파일을 명시하여 add하는 시연을 추가한다.')
add('체크포인트와 /rewind','Claude Code가 추적한 편집과 대화를 되돌리는 기능입니다.',['대화·파일·둘 다 복구할지 선택 내용을 확인','셸만으로 바뀐 파일은 추적되지 않을 수 있음','이메일·DB·배포 같은 외부 영향은 복구하지 못함','Git이나 별도 백업을 대체하는 기능은 아님'],note='현재 문서는 Claude의 편집 도구가 먼저 편집한 파일에 이후 셸 변경이 생기면 그 파일의 복구에 포함될 수 있다고 설명한다. 따라서 “모든 Bash 변경은 항상 제외” 또는 “모든 변경 복구”라고 단정하지 않는다.',src=['checkpointing'])
add('실습 2 · 작은 HTML 안내문','10분 · 체크리스트를 브라우저에서 읽는 페이지로 만들기',code='output/checklist.md를 바탕으로 output/welcome.html을 만들어줘.\n외부 라이브러리·서버·외부 전송 없이 HTML 한 파일로 만들어줘.\n체크박스를 넣고 좁은 화면에서도 읽기 쉽게 해줘.\n자료 충돌은 “확인 필요”로 표시하고 원본은 유지해줘.\n검증한 항목과 직접 확인하지 못한 항목을 나눠 보고해줘.',note='완료 후 탐색기에서 welcome.html을 더블클릭한다. 체크박스가 눌리는지, 390px 정도의 좁은 창에서 가로 넘침이 없는지 확인한다. 새로고침 후 선택 유지 기능은 요구하지 않았으므로 사라져도 실패가 아니다.',kind='lab')
add('데이터 보호와 프롬프트 인젝션','읽은 문서에 적힌 지시를 무조건 따라서는 안 됩니다.',['실제 주민번호·연봉·평가·비밀키 대신 가상 데이터 사용','외부 문서의 “규칙을 무시하고 파일 전송”은 의심 신호','데이터 사용·보관·학습 정책은 계약과 계정 설정에 따라 확인','민감한 파일은 분리하고 권한·네트워크 접근도 제한'],note='프롬프트 인젝션은 참고 자료가 에이전트의 행동 지시처럼 작동하도록 유도하는 공격이다. 믿을 수 있는 도구가 가져온 내용도 신뢰할 수 없는 작성자의 텍스트일 수 있다. 강의 중에는 실제 공격용 외부 연결을 하지 않는다.',src=['security','data-usage'])
add('지침·권한·샌드박스의 역할','좋은 부탁과 기술적인 제한을 구별합니다.',['지침: “원본을 바꾸지 마” 같은 행동 요청','권한 규칙: 도구의 허용·거부 조건','샌드박스: 명령의 파일·네트워크 접근 경계를 제한','한 가지 장치가 모든 종류의 도구를 막는 것은 아님'],note='샌드박스가 켜져 있어도 MCP나 다른 실행 경로까지 같은 경계라고 가정하지 않는다. 지원 OS와 도구 범위를 공식 문서에서 확인한다. 최소 권한, 검토, 백업을 함께 사용한다.',src=['sandboxing'])
section('05 · 컨텍스트와 프로젝트 지침','같은 설명을 반복하지 않고 작업을 이어 가기','35분 · 세션과 기억')
add('긴 대화를 관리하는 기준','목표가 바뀌면 대화도 정리할 시점입니다.',['관련 없는 과제를 같은 세션에 계속 쌓지 않기','큰 로그는 핵심 오류와 필요한 범위를 추리기','중요 결정은 대화뿐 아니라 파일에 기록','요약 뒤에는 핵심 제약과 현재 파일 상태를 다시 확인'],note='자동 압축이 일어나도 세부 맥락이 전부 그대로 유지된다고 가정하지 않는다. “어디까지 했는가”를 짧은 파일로 남겨 두면 재시작과 협업 모두 쉬워진다.',src=['context'])
add('세션을 정리하고 이어 쓰기','명령을 실행하는 위치가 다릅니다.',code='/compact 현재 목표, 수정 파일, 검증 결과, 남은 일을 보존해줘\n/clear',label='Claude Code 내부 · 두 명령은 목적에 따라 따로 사용',items=['claude -c: 현재 디렉터리의 최근 대화 계속하기','claude -r: 재개할 대화 선택 / /resume: 대화 안에서 재개'],note='/compact는 대화를 요약해 컨텍스트를 줄인다. /clear는 새 세션을 시작하는 용도이며 파일 변경을 취소하지 않는다. 두 명령을 무조건 연속 실행하는 절차가 아니라고 강조한다.',src=['commands','cli-reference'])
add('CLAUDE.md는 프로젝트 안내서','매번 필요한 짧은 규칙을 파일로 둡니다.',['프로젝트 목적, 자료 위치, 실행·검증 방법','변경 범위와 결과 보고 방식','코드만 읽어서는 알기 어려운 팀의 결정','/init으로 초안을 만들 수 있지만 내용은 검토'],note='CLAUDE.md는 Markdown 텍스트다. 긴 매뉴얼 전체를 복사하기보다 필요한 문서를 링크한다. 모델의 문맥으로 읽히는 지침이므로 강제 보안 정책이 아니다.',src=['memory'])
add('실습용 CLAUDE.md 예시','workshop/CLAUDE.md로 직접 만들 때 사용할 내용입니다.',code='# 온보딩 실습\n- materials/는 원본 자료다. 수정하지 않는다.\n- 결과는 output/에 작성한다.\n- 한국어로 작성하고 사실에 근거 파일명을 붙인다.\n- 자료 충돌과 누락은 확인 필요로 표시한다.\n- 실제 개인정보, 외부 전송, 배포를 사용하지 않는다.\n- 완료 시 변경 파일, 확인 결과, 미확인 사항을 보고한다.',label='파일 내용 · CLAUDE.md',note='예제 파일은 examples에만 제공한다. 수강자가 검토한 뒤 workshop으로 복사한다. 이 문구만으로 파일 시스템이 읽기 전용이 되는 것은 아니다. 보안 제한이 필요하면 별도 권한 설정을 사용한다.',src=['memory'])
add('지침과 자동 메모리','사람이 정한 규칙과 모델이 저장한 관찰을 구분합니다.',['CLAUDE.md: 사람이 검토하는 프로젝트 지침','Auto memory: 반복되는 선호·수정사항을 기록','/memory에서 기억 내용을 확인하고 정리','잘못 저장된 가정이나 비밀정보는 남기지 않기'],note='기억이 생긴다고 해서 영구적으로 모든 대화를 기억하는 것은 아니다. 공유 프로젝트 규칙과 개인 선호를 분리하고, 지침 간 충돌이 생기면 중복을 줄인다.',src=['memory'])
add('설정 파일의 범위','내 모든 프로젝트에 적용할지, 이 프로젝트에만 적용할지 선택합니다.',['~/.claude/settings.json: 개인 사용자 설정','.claude/settings.json: 공유 프로젝트 설정','.claude/settings.local.json: 프로젝트의 개인 설정','조직 관리 설정은 개인 설정보다 우선할 수 있음'],note='기존 설정을 덮어쓰지 않고 해당 키를 병합한다. JSON에는 일반적인 주석을 넣을 수 없으며 마지막 항목 뒤 쉼표도 오류가 될 수 있다. 설정과 비밀키를 같은 파일에 넣어 커밋하지 않는다.',src=['settings'])
add('모델 선택과 사용량','작업 난도·속도·비용을 함께 봅니다.',['/model: 계정에서 제공되는 모델 선택','짧은 정리와 복잡한 원인 분석에 같은 자원이 필요하지 않음','모델 이름·가용성·effort 옵션은 환경별로 확인','/usage로 사용량, /context로 문맥 사용 확인'],note='특정 모델이 항상 가장 좋다고 단정하지 않는다. 대표 작업 몇 개를 같은 기준으로 비교한다. 도구 출력과 재시도가 비용을 늘릴 수 있으므로 프롬프트 길이만 줄여서는 해결되지 않을 수 있다.',src=['model-config','costs','commands'])
add('다음 세션에 넘길 인수인계','작업 상태는 짧고 검증 가능하게 남깁니다.',code='output/handoff.md에 다음 내용을 정리해줘.\n1. 현재 목표와 확정한 결정\n2. 수정한 파일과 변경 이유\n3. 실행한 검증과 그 결과\n4. 아직 확인하지 못한 사항\n5. 다음 작업 한 가지\n비밀정보는 포함하지 마.',note='새 세션에서는 이 파일을 읽히고 실제 파일 상태와 맞는지 먼저 확인한다. 이전 에이전트의 보고서는 증거의 위치를 안내하는 자료이지 검증을 생략하는 허가가 아니다.')
section('06 · Skills, MCP, Hooks','반복 절차와 외부 도구를 구분해서 확장하기','45분 · 기능 비교 + 세 번째 실습')
add('확장 기능을 고르는 기준','무엇이 반복되거나 부족한지부터 확인합니다.',['CLAUDE.md: 항상 참고해야 하는 프로젝트 지침','Skill: 필요할 때 실행하는 재사용 절차','MCP: 외부 데이터와 도구 연결','Hook: 특정 이벤트에 자동 실행 / Plugin: 기능 묶음 배포'],note='모든 기능을 한꺼번에 설치할 필요는 없다. 반복되는 문서 검토 절차만 필요하면 Skill 하나로 시작한다. 서브에이전트는 다음 장에서 별도 작업 문맥을 갖는 역할로 설명한다.',src=['skills','mcp','hooks-guide','plugins'])
add('Skill의 구조와 호출','폴더 안의 SKILL.md에 설명과 절차를 작성합니다.',['프로젝트 범위: .claude/skills/이름/SKILL.md','개인 범위: ~/.claude/skills/이름/SKILL.md','직접 실행: /이름 + 필요한 인자','설명(description)은 언제 사용할지 판단하는 단서'],note='YAML frontmatter는 --- 사이의 메타데이터 부분이다. 사용자 실행만 원하면 disable-model-invocation을 true로 설정한다. Skill에 도구 권한을 무조건 넓게 주지 않는다.',src=['skills'])
add('문서 검토 Skill 예시','직접 /review-onboarding으로 실행하는 절차입니다.',code='---\nname: review-onboarding\ndescription: 온보딩 결과물의 근거와 누락을 검토\ndisable-model-invocation: true\n---\nmaterials/와 output/을 비교한다.\n시간·장소·담당자·준비물의 충돌과 누락을 찾는다.\n파일은 수정하지 않고 문제, 근거, 수정 제안을 표로 보고한다.\n근거가 없으면 추정하지 않고 확인 필요로 분류한다.',label='파일 내용 · .claude/skills/review-onboarding/SKILL.md',note='이 예제는 코드 실행이나 배포를 포함하지 않는다. Skill의 “수정하지 않는다”는 자연어 지시이며 도구 격리는 아니다. 엄격한 읽기 전용 역할은 다음 장의 tools 제한 예제와 비교한다.',src=['skills'])
add('실습 3 · 절차 재사용','8분 · Skill 파일 작성 → 호출 → 결과 확인',['examples의 Skill을 workshop/.claude/skills 아래에 배치','/review-onboarding으로 직접 실행','지적 사항 중 하나를 원문에서 검증','목적이 같아도 입력이 바뀌면 다시 검사되는지 확인'],note='파일이 보이지 않으면 이름과 대소문자, 폴더 구조를 확인한다. 필요하면 세션을 재시작하고 / 메뉴에서 찾는다. 설치한 Skill이 자동으로 항상 실행되는 것은 아니다.',kind='lab',src=['skills'])
add('MCP는 도구 연결 규약','Model Context Protocol: 모델 앱과 외부 도구가 연결되는 표준 방식',['예: 문서 검색, 이슈 조회, 데이터베이스 질의','Claude Code가 MCP 서버의 도구를 호출','서비스 인증·접근 권한은 별도 설정 필요','연결한다고 데이터가 모두 자동으로 학습되는 것은 아님'],note='MCP 자체가 특정 데이터베이스나 모델은 아니다. 읽기 도구와 쓰기 도구를 구분한다. 외부 업무 시스템을 실제로 연결하는 실습은 관리자 승인과 테스트 계정을 준비한 뒤 별도로 진행한다.',src=['mcp'])
add('MCP 연결 시연 · 강사 선택 실습','Sentry 공식 예시 · 계정과 접근 권한이 있을 때만 실행',code='claude mcp add --transport http sentry https://mcp.sentry.dev/mcp\nclaude mcp list',label='OS 터미널 · 실제 외부 서비스 연결 예',items=['Claude 내부 /mcp에서 연결 상태와 로그인 절차 확인','서버 제공자·권한·데이터 전송 범위 검토 후 사용'],note='이 수업의 필수 실습에는 MCP 계정이 필요 없다. add는 설정 등록이며 인증과 실제 연결 성공은 별도다. OAuth 화면에서 범위를 확인한다. 필요 없어진 연결은 claude mcp remove sentry로 제거하고 서비스 측 권한도 점검한다.',src=['mcp'])
add('MCP 운영에서 생기는 문제','설정됨·인증됨·도구 호출 성공은 서로 다른 상태입니다.',['연결 실패: URL·네트워크·서버 상태 확인','인증 실패: 계정·토큰 만료·권한 범위 확인','도구 과다: 필요한 서버만 연결해 문맥·선택 부담 줄이기','외부 결과: 신뢰할 수 없는 지시가 섞였는지 확인'],note='API 키를 명령줄에 직접 쓰면 셸 이력이나 로그에 남을 수 있다. 제공자가 안내한 안전한 인증 방식을 따른다. 민감한 연동 설정을 프로젝트 저장소에 그대로 공유하지 않는다.',src=['mcp','security'])
add('Hook은 이벤트에 반응하는 자동화','모델의 기억에 맡기지 않고 특정 시점에 프로그램을 실행합니다.',['PreToolUse: 도구 실행 전 검사','PostToolUse: 도구 실행 성공 후 후처리','Stop: 응답 종료 시점의 확인','자연어 권고보다 일관되지만 잘못된 코드도 매번 실행됨'],note='Hook은 Claude의 권한으로 명령을 실행하므로 설치 전에 내용을 읽는다. 실패 처리는 이벤트별로 다르다. 모든 Hook의 오류가 모든 행동을 차단한다고 가정하지 않는다.',src=['hooks-guide'])
add('Hook 설정 예제 · 편집 후 알림','파일 수정이 발생했음을 출력하는 작은 예제입니다.',code='{"hooks":{"PostToolUse":[{\n  "matcher":"Edit|Write",\n  "hooks":[{\n    "type":"command",\n    "command":"echo Edit_completed_review_diff"\n  }]\n}]}}',label='파일 내용 · .claude/settings.json의 hooks 키로 병합',items=['예제는 내용을 검사하거나 위험한 수정을 차단하지 않음'],note='기존 settings.json을 통째로 대체하지 않는다. /hooks에서 등록 여부를 확인하고 테스트 파일 편집으로 발동 여부를 확인한다. 출력 노출 방식은 UI에 따라 다를 수 있다. 실무의 포맷터나 검사는 설치·경로·입력 검증을 추가한다.',src=['hooks-guide'])
add('Plugins와 공유','Skill·Hook·서브에이전트·MCP 설정 등을 묶어 배포할 수 있습니다.',['/plugin에서 설치·관리 기능 확인','필요한 기능과 관리 주체가 분명한 것부터 선택','설치 전 실행 코드·요청 권한·업데이트 출처 확인','팀 배포는 버전과 변경 기록을 함께 관리'],note='플러그인은 단순 설명 문서가 아니라 코드를 실행할 수 있는 구성 요소를 포함한다. 수업에서 임의의 커뮤니티 플러그인을 전원 설치시키지 않는다. 예제 Skill 하나를 공유하는 것으로도 충분하다.',src=['plugins','commands'])
section('07 · 에이전트와 고급 자동화','작업 분할, 독립 검토, 제한된 자동 실행','50분 · 강사 시연 중심')
add('서브에이전트가 필요한 때','별도 문맥에서 좁은 작업을 수행하고 결과를 돌려받습니다.',['긴 자료 조사나 독립적인 검토를 분리','역할마다 사용할 도구와 출력 형식을 제한','주 에이전트는 결과를 통합하고 최종 확인','위임한 작업도 시간·토큰을 소비'],note='별도 문맥이라고 해서 완벽히 독립된 판단이나 무오류가 보장되는 것은 아니다. 단순한 문장 수정에 여러 에이전트를 사용하는 것은 오히려 느릴 수 있다.',src=['sub-agents'])
add('읽기 전용 검토 에이전트','파일 탐색·읽기 도구만 허용하는 예제입니다.',code='---\nname: evidence-reviewer\ndescription: 온보딩 문서의 사실과 근거 검토\ntools: Read, Glob, Grep\n---\nmaterials/와 output/을 대조한다.\n각 문제를 [파일 / 문제 / 근거 / 제안]으로 보고한다.\n확실한 문제와 추가 확인 사항을 구분한다.\n파일을 변경하지 않는다.',label='파일 내용 · .claude/agents/evidence-reviewer.md',note='Bash를 넣지 않은 이유를 설명한다. 셸은 읽기 명령만 가능한 도구가 아니기 때문이다. /agents로 에이전트를 관리하고 필요하면 새 세션에서 로딩을 확인한다.',src=['sub-agents'])
add('위임 요청에는 계약이 필요하다','역할·입력·범위·완료 조건을 한 번에 전달합니다.',code='evidence-reviewer 서브에이전트로 검토해줘.\n입력: materials/와 output/welcome.html\n범위: 사실 오류, 누락, 자료 충돌만 확인\n결과: 중요도, 파일 위치, 근거, 수정 제안\n수정은 하지 말고 근거 없는 추측은 제외해줘.',note='서브에이전트에게 대화 전체가 자동으로 같은 방식으로 전달된다고 가정하지 않는다. 필요한 파일과 목표를 명시한다. 주 에이전트는 반환된 결과에서 실제 문제인지 원문과 다시 확인한다.',src=['sub-agents'])
add('작업자와 검토자를 분리하기','작성 결과를 별도 기준으로 다시 점검합니다.',['작업자: 요구사항에 맞는 결과물을 생성','검토자: 원본과 대조하고 실패 사례를 탐색','통합자: 중복·오탐을 제거하고 필요한 수정 결정','최종 책임: 사람이 실제 산출물과 위험을 확인'],note='검토자에게 작성자의 완료 선언만 주지 않는다. 원본과 산출물, 수용 기준을 함께 준다. 같은 모델이 검토하면 같은 가정을 공유할 수 있으므로 독립적인 수치·실행·화면 검사도 필요하다.')
add('병렬 처리할 수 있는 일','서로 기다리지 않아도 되는 작업에 적합합니다.',['가능: 사실 검토와 화면 가독성 검토를 따로 진행','가능: 서로 다른 문서의 초안 작성','주의: 같은 파일을 동시에 편집하면 충돌 가능','순차가 적합: 조사 결과가 있어야 시작할 수 있는 구현'],note='파일별 담당자를 지정하고 통합 담당자를 한 명 둔다. 병렬 실행이 단일 작업의 품질을 자동으로 올려 주지는 않는다. 결과 비교와 통합 시간이 늘어난다는 점까지 계산한다.',src=['agents','agent-teams'])
add('worktree로 작업 폴더 분리','하나의 Git 저장소에서 서로 다른 작업 디렉터리를 사용할 수 있습니다.',code='claude --worktree onboarding-copy',label='OS 터미널 · 커밋이 있는 Git 저장소 필요',items=['별도 브랜치·폴더에서 다른 작업과 분리','완료 후 차이를 검토하고 통합','같은 DB·계정·포트까지 자동으로 분리되지는 않음'],note='입문 과정의 필수 실습은 아니다. 저장되지 않은 파일이나 비밀 설정이 복제되지 않을 수 있다. 작업 디렉터리를 지우기 전에 필요한 변경을 보존했는지 확인한다.',src=['common-workflows','cli-reference'])
add('Agent teams · 실험적 기능','여러 독립 세션이 공유 작업과 메시지로 협업합니다.',['리드가 역할과 전체 목표를 관리','동료 세션이 조사 결과를 공유하고 협의','기본 비활성화이며 재개·조정 등의 제한이 있음','작은 과제는 단일 세션이나 서브에이전트가 더 단순'],note='2026-11-02 공식 문서 기준 실험적 기능이다. 수업 핵심 흐름이 이 기능에 의존하지 않게 한다. 멤버가 많으면 토큰과 조정 부담이 커진다.',src=['agent-teams'])
add('Agent teams 활성화 예시','별도 실습 환경에서 선택적으로 사용합니다.',code='{"env":{\n  "CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS":"1"\n}}',label='파일 내용 · settings.json에 병합 후 새 세션',items=['요청 예: “정확성 검토와 사용성 검토 팀을 구성해줘.”','담당 범위, 수정 금지, 보고 형식, 종료 조건을 명시'],note='이 예제 설정은 자동 활성화하지 않는다. 중단할 때 동료 세션이 종료되었는지 확인한다. 실험 기능이 제공되지 않으면 두 개의 독립 검토 요청으로 같은 교육 목표를 달성할 수 있다.',src=['agent-teams'])
add('비대화형 실행 · claude -p','한 번 요청하고 결과를 출력한 뒤 종료하는 방식입니다.',code='claude -p "materials/policy.md의 준비물만 요약해줘" --tools "Read" --disallowedTools "mcp__*" --output-format json --max-turns 3',label='OS 터미널 · workshop 폴더에서',items=['스크립트나 CI에 연결 가능 / 실행 결과와 오류를 따로 확인','도구 범위·턴 제한·예산·시간 제한을 설계'],note='이 예제는 내장 도구를 Read로 제한하고 MCP 도구를 거부한다. Hook 등 환경 사용자 설정은 별도로 검토한다. 조직 정책으로 읽기가 거부되면 결과를 확인하고 중단한다. 비대화형 실행은 대화형 승인 팝업에 기대지 않도록 구성해야 한다. JSON 출력에는 메타데이터와 결과 필드가 있으므로 파싱 전에 구조를 확인한다.',src=['headless','cli-reference'])
add('자동화의 출력 계약','“완료했습니다” 한 문장으로 다음 단계를 실행하지 않습니다.',['필요한 필드: 상태, 산출물, 검증 결과, 미해결 항목','JSON 문법이 맞아도 내용이 사실인지 별도 확인','실패·권한 거부·예산 초과 시 다음 단계 중단','외부 전송·병합·배포 전 검토 단계를 둠'],note='반복 작업은 같은 입력을 재실행해도 중복 메일이나 중복 기록이 생기지 않도록 설계한다. 출력 파일이 일부만 생성된 경우를 실패로 처리하는 기준도 정한다.',src=['headless'])
add('Agent SDK로 넘어갈 때','에이전트 실행을 프로그램 안에서 제어해야 할 때 사용합니다.',['Python·TypeScript에서 실행과 결과 스트림 제어','도구·권한·세션·구조화된 결과를 앱에 통합','단순 반복은 CLI -p로 먼저 검증','서비스화에는 인증, 격리, 로그, 예산, 재시도 정책 필요'],note='SDK 사용은 개발자 협업 주제로 둔다. SDK는 모델 호출만 하는 API와 달리 도구와 에이전트 루프를 포함하는 실행 기반이다. 이 수업에서는 SDK 코드를 실행하는 데 필요한 별도 개발 환경을 요구하지 않는다.',src=['agent-sdk/overview'])
add('고급 에이전트 설계 패턴','과업의 구조에 맞춰 최소한의 복잡성으로 구성합니다.',['연쇄: 조사 결과를 다음 작성 단계의 입력으로 사용','라우팅: 문서 종류에 따라 적절한 처리로 분기','병렬: 독립 검토 후 결과 통합','평가·수정: 기준 검사 후 제한된 횟수로 개선'],note='동일한 가상 온보딩 자료를 예로 든다. 파일 분류는 라우팅, 초안 뒤 사실 검사는 평가·수정이다. 오케스트레이터가 작업을 동적으로 나눌 수도 있지만 먼저 간단한 순서를 검증한다.',src=['agents'])
add('멈출 조건과 성공 기준','계속 일하는 것과 목표를 달성하는 것은 다릅니다.',['성공: 정의한 산출물과 검증 기준 충족','중단: 근거 부족, 권한 부족, 비용·시간 한도 초과','실패 반복: 같은 오류가 반복되면 사람에게 원인 보고','지표: 정확도, 누락, 소요 시간, 비용, 수동 수정량'],note='교육용 예산 예: 최대 3번 수정하고 해결하지 못하면 미완료로 보고한다. 품질 평가용 고정 사례에는 자료 충돌, 빈 자료, 잘못된 형식도 포함한다. 무조건 자율 실행 시간이 길수록 좋다는 생각을 교정한다.')
section('08 · 종합 실습과 업무 적용','작은 온보딩 키트를 만들고 검토하기','70분 · 제작 40 + 동료 검토 10 + 퀴즈 10 + 적용 10')
add('종합 과제 · 온보딩 키트','가상 회사 “새봄랩”의 신입사원 안내 자료를 만듭니다.',['입력: materials/의 정책·FAQ·일정','결과: checklist.md, welcome.html, review.md','추가: handoff.md에 결정과 남은 질문 기록','제약: 원본 보존, 외부 전송 없음, 충돌·누락 표시'],note='이미 만든 초안을 재사용해도 된다. 평가는 사실과 기능 중심이며 디자인 취향을 채점하지 않는다. 모든 자료는 가상임을 결과물에도 적도록 한다.',kind='lab')
add('종합 과제 · 단계별 시간','40분 동안 한 번의 완성된 작업 루프를 수행합니다.',['0~7분: 읽기·충돌 파악·완료 기준 작성','7~22분: 문서와 HTML 생성, 파일 변경 검토','22~32분: 별도 검토와 브라우저 동작 확인','32~40분: 수정·재확인·인수인계 작성'],note='진행이 느린 수강자는 HTML 꾸미기 대신 기본 내용과 체크박스 동작을 우선한다. 빠른 수강자는 자료를 고치지 않고 누락·충돌 확인 표시를 개선한다. 추가 기능을 무제한으로 늘리지 않는다.')
add('종합 과제 · 시작 프롬프트','범위를 정하고 먼저 계획을 검토합니다.',code='새봄랩의 가상 온보딩 키트를 만들려고 해.\nmaterials/를 읽고 산출물별 작성·검증 계획을 먼저 제시해줘.\n결과는 output/checklist.md, welcome.html, review.md야.\n시간·장소가 충돌하면 둘 다 제시하고 확인 필요로 남겨줘.\nHTML은 외부 의존성 없이 만들고 원본은 변경하지 마.\n마지막에 검증 결과와 남은 일을 handoff.md에 적어줘.',note='계획을 확인한 뒤 구현을 요청한다. 이 프롬프트는 수업용 예시이며 모든 과업에 쓰는 만능 프롬프트는 아니다. 실제 업무에서는 검증 명령과 승인 경로를 프로젝트에 맞게 조정한다.')
add('수용 기준 · 통과 여부를 직접 확인','“잘 만들었다” 대신 관찰 가능한 조건으로 평가합니다.',['필수 파일 4개가 존재하고 열리는가?','출근 시각·장소 충돌과 식대 미확정이 표시되는가?','HTML이 390px 폭에서도 읽히고 체크박스가 작동하는가?','원본 변경·외부 요청 없이 근거를 추적할 수 있는가?'],note='review.md에는 확인 방법과 결과, 미확인 사항을 구분한다. 브라우저 개발자 도구를 못 쓰는 경우 네트워크 무요청은 강사가 확인한다. 확인하지 않은 항목을 통과라고 쓰지 않는 것도 중요한 평가 항목이다.')
add('동료 검토 · 10분','상대방의 산출물에서 문제 하나를 구체적으로 찾아봅니다.',['근거 확인: 문장 2개와 숫자 1개를 원문과 대조','동작 확인: 체크박스, 좁은 화면, 링크','범위 확인: 원본 파일 변경 여부','피드백 형식: 위치 → 관찰 → 영향 → 수정 제안'],note='오류가 없으면 억지로 지적하지 않는다. 확인한 범위와 남은 불확실성을 적는다. “보기 싫다” 대신 “좁은 화면에서 시간 항목이 잘려 읽을 수 없다”처럼 관찰을 전달한다.')
add('막혔을 때의 진단 순서','실행 환경 문제와 요청 문제를 분리합니다.',['현재 폴더·입력 위치·파일 이름부터 확인','오류 전문과 마지막 실행 동작을 확보','권한·인증·네트워크 문제인지 분류','최소한의 재현 사례로 다시 시도'],note='오류를 숨기려고 검증을 삭제하거나 모든 권한을 허용하지 않는다. 명령이 없다는 오류라면 필요한 프로그램의 설치 여부부터 본다. 같은 수정이 계속 실패하면 새로운 가설을 세운다.')
add('실패 패턴과 수정 방법','진행 속도보다 다시 확인할 수 있는 작업이 중요합니다.',['큰 요청 한 번 → 단계와 완료 기준으로 나누기','모든 파일 읽기 → 필요한 자료부터 범위 좁히기','근거 없는 확정 → 출처와 미확정 표시 요청','검증 생략 → 실제 실행·원문 대조·화면 확인'],note='수강자에게 자신이 겪은 실패를 한 가지 적게 한다. 다음 요청에서 무엇을 바꿀지 구체적으로 말하게 한다. 좋은 결과물 자체보다 반복 가능한 작업 습관을 남긴다.')
add('퀴즈 1 · 파일이 바뀌지 않는 이유','셸 창에 “문서를 요약해줘”라고 입력했더니 오류가 납니다.',['A. 모델이 한국어를 지원하지 않는다','B. Claude Code를 실행하지 않은 셸 입력이다','C. 무조건 관리자 권한이 필요하다'],answer='B. 먼저 올바른 폴더에서 claude를 실행하고 대화 입력창에 요청합니다.',note='입력 위치를 다시 확인한다. 실제 오류 문구에 따라 다른 원인도 있을 수 있지만 이 사례의 핵심은 셸과 에이전트 대화의 구별이다.',kind='quiz')
add('퀴즈 2 · /clear의 효과','대화를 비우면 생성한 파일도 원래대로 돌아갈까요?',['A. 대화와 파일이 모두 되돌아간다','B. 대화는 새로 시작하지만 파일 변경은 남는다'],answer='B. 파일 복구는 /rewind, Git, 백업 등 적용 범위에 맞는 방법을 사용합니다.',note='중단, 대화 초기화, 파일 복구가 서로 다른 작업이라는 점을 다시 강조한다.',kind='quiz',src=['commands','checkpointing'])
add('퀴즈 3 · 어떤 확장 기능일까?','문서 검토 절차를 /review-onboarding으로 재사용하고 싶습니다.',['A. Skill','B. MCP 서버','C. 샌드박스'],answer='A. 절차 재사용은 Skill, 외부 도구 연결은 MCP, 실행 경계 제한은 샌드박스입니다.',note='Hook은 이벤트에 자동 실행하는 기능이라는 점도 추가 질문으로 확인한다.',kind='quiz',src=['skills'])
add('퀴즈 4 · 에이전트의 완료 보고','“테스트가 통과했습니다”라는 보고만 받았습니다.',['다음으로 확인할 것은 무엇인가요?','실행한 명령, 결과, 검증 범위, 미확인 항목을 생각해 보세요.'],answer='실제 실행 기록과 결과를 확인합니다. 테스트 통과와 모든 요구사항 충족은 같지 않습니다.',note='수강자에게 온보딩 페이지의 체크박스 테스트와 자료 정확도 검증이 왜 다른지 설명하게 한다.',kind='quiz')
add('내 업무에 적용할 첫 과제','작고, 반복되며, 결과를 쉽게 확인할 수 있는 작업을 고릅니다.',['예: 공개 자료의 비교표, 가상 FAQ, 문서 형식 정리','입력 자료와 산출물 경로를 먼저 정하기','실패 비용이 낮은 복사본으로 시험하기','성공 기준과 사람의 검토 시점을 기록하기'],note='인사 업무에서는 채용·평가 결정을 자동화하는 대신 승인된 자료의 편집 보조부터 시작한다. 민감정보 사용 여부는 조직 정책과 담당자 확인에 따른다. 이 슬라이드는 법률 판단 지침이 아니다.')
add('2주 도입 계획 · 제안','작은 실험으로 효과를 확인한 뒤 범위를 넓힙니다.',['1~2일: 동일한 작은 작업 3개를 수동·AI 방식으로 비교','3~5일: 반복 설명을 CLAUDE.md와 Skill로 정리','2주차: 읽기 전용 검토 역할과 평가 사례 추가','확대 조건: 오류·비용·수정 시간을 실제로 기록'],note='제시한 일정은 강의용 제안이며 제품의 보장된 효과가 아니다. 절감 시간만 보지 말고 검토와 복구에 든 시간도 포함한다.')
add('업무 실행 전 체크리스트','범위·권한·근거·검증·복구를 확인합니다.',['올바른 폴더와 계정인가? 민감정보는 분리했는가?','완료 기준과 출력 경로가 명확한가?','변경과 외부 영향에 필요한 권한만 허용했는가?','실제 결과를 검증하고 남은 문제를 기록했는가?'],note='이 다섯 단어를 암기시키기보다 자신이 만든 산출물에 적용하게 한다. 마지막으로 다음 세션에 넘길 handoff.md를 서로 읽어 보고 이해 가능한지 확인한다.')
section('부록 · 다시 찾아보기','명령 치트시트, 용어, 공식 자료','자습과 수업 후 참고')
add('치트시트 · OS 터미널','Claude Code 밖에서 실행하는 명령',code='claude --version\nclaude doctor\nclaude --permission-mode default\nclaude --permission-mode plan\nclaude -c\nclaude -r\nclaude --help',label='OS 터미널 · 목적에 맞는 한 줄 선택',note='명령을 한 번에 모두 실행하는 스크립트가 아니다. default는 Manual 모드 설정값이다. 설치 방식별 업데이트 절차는 공식 setup 문서를 확인한다.',src=['cli-reference','setup'])
add('치트시트 · Claude Code 내부','/로 시작하는 명령은 대화 입력창에서 사용합니다.',['/help · /status · /usage: 도움말과 상태','/model · /permissions: 모델과 권한','/compact · /clear · /resume: 대화 관리','/memory · /agents · /mcp · /hooks · /plugin: 확장 관리'],note='현재 환경의 / 메뉴를 최종 기준으로 삼는다. 이 외에 /diff와 /rewind로 변경 확인·복구를 할 수 있다. 메뉴와 가용성은 버전·계정·조직 정책에 따라 달라질 수 있다.',src=['commands'])
add('용어집 · 기본','낯선 용어는 작업과 연결해서 기억합니다.',['프롬프트: 요청 내용 / 컨텍스트: 현재 참고하는 정보','토큰: 모델이 처리하는 조각 / 추론: 입력으로 답 생성','CLI: 명령 인터페이스 / 디렉터리: 폴더','diff: 변경 차이 / 커밋: Git에 남긴 선택된 상태'],note='토큰 수와 글자 수를 같은 것으로 설명하지 않는다. 추론은 기술 문맥에서 inference를 뜻하며 모든 출력이 검증된 논리적 결론이라는 의미는 아니다.')
add('용어집 · 고급','반복 절차·도구 연결·작업 분리를 구별합니다.',['Skill: 필요할 때 불러오는 절차와 지식','MCP: 외부 도구·자료 연결 규약','Hook: 이벤트에 반응하는 실행 규칙','Subagent: 위임한 작업 역할 / SDK: 프로그램 통합 도구'],note='Agent teams는 여러 독립 세션을 조정하는 실험 기능이다. worktree는 Git 작업 디렉터리 분리이며 샌드박스와 같은 뜻이 아니다.')
add('공식 자료 · 시작과 일상 사용','각 슬라이드 아래 출처와 강사 노트에서도 바로 열 수 있습니다.',['Overview · Quickstart · Terminal guide · Setup','Interactive mode · Commands · Common workflows','Permission modes · Checkpointing · Best practices'],note='검색 결과의 오래된 블로그보다 현재 공식 문서와 설치된 버전의 도움말을 우선한다. 2026-11-02에 확인한 자료이며 이후 변경될 수 있다.',src=['overview','quickstart','terminal-guide','setup','interactive-mode','commands','common-workflows','permission-modes','checkpointing','best-practices'])
